R = "us-east-1"
NAME = "alcove-acs971378df"
B64 = ""

CMD = ("set -e; mkdir -p /app; cd /app; echo '" + B64 + "' | base64 -d | tar xz; "
       "npm install --omit=dev --no-audit --no-fund --loglevel=error; exec node server.js")

async def main():
    existing = await call_boto3(service_name="lightsail", operation_name="GetContainerServices", region_name=R)
    svc = await call_boto3(service_name="lightsail", operation_name="CreateContainerService", region_name=R, params={
        "serviceName": NAME,
        "power": "micro",
        "scale": 1,
        "deployment": {
            "containers": {
                "alcove": {
                    "image": "public.ecr.aws/docker/library/node:20-bookworm-slim",
                    "command": ["/bin/sh", "-c", CMD],
                    "environment": {"PORT": "3000", "NODE_ENV": "production"},
                    "ports": {"3000": "HTTP"},
                }
            },
            "publicEndpoint": {
                "containerName": "alcove",
                "containerPort": 3000,
                "healthCheck": {
                    "healthyThreshold": 2, "unhealthyThreshold": 5,
                    "timeoutSeconds": 5, "intervalSeconds": 10,
                    "path": "/healthz", "successCodes": "200",
                },
            },
        },
    })
    s = svc["containerService"]
    return {"pre_existing": [c["containerServiceName"] for c in existing.get("containerServices", [])],
            "name": s["containerServiceName"], "state": s["state"],
            "url": s.get("url"), "power": s["power"], "scale": s["scale"],
            "cmd_len": len(CMD)}

result = await main()
result

