headers['authorization'] = `AWS4-HMAC-SHA256 Credential=[REDACTED:value]}/${scope}, SignedHeaders=${signedHeaders}, Signature=${sig}`;

const req = https.request({ host, path: '/', method: 'POST', headers }, (res) => {
  let d = ''; res.on('data', x => d += x);
