// Restore the dumped umami data into the target Postgres.
const { Client } = require('/tmp/node_modules/pg');
const copyFrom = require('/tmp/node_modules/pg-copy-streams').from;
const fs = require('fs');
const { pipeline } = require('stream/promises');

const HOST = process.argv[2], PASS = [REDACTED:conn-password]];
const manifest = JSON.parse(fs.readFileSync('/tmp/dump/manifest.json', 'utf8'));

(async () => {
  const c = new Client({ host: HOST, port: 5432, user: 'umami', password: [REDACTED:value],
                         database: 'umami', connectionTimeoutMillis: 20000 });
  await c.connect();
  const names = manifest.map(m => `"${m.table}"`).join(', ');
  // Replace whatever umami seeded on first boot with the exact pre-restart state.
  await c.query(`TRUNCATE ${names} RESTART IDENTITY CASCADE`);
  let total = 0;
  for (const m of manifest) {
    if (m.rows === 0) continue;
    const stream = c.query(copyFrom(`COPY "${m.table}" (${m.cols.join(',')}) FROM STDIN (FORMAT csv)`));
    await pipeline(fs.createReadStream(`/tmp/dump/${m.table}.csv`), stream);
    const n = (await c.query(`select count(*)::int c from "${m.table}"`)).rows[0].c;
    console.log(`${m.table}: restored ${n}/${m.rows}`);
    if (n !== m.rows) throw new Error(`row count mismatch on ${m.table}: ${n} != ${m.rows}`);
    total += n;
  }
  console.log('TOTAL RESTORED', total);
  await c.end();
})().catch(e => { console.error('ERR', e.message); process.exit(1); });
