'use strict';

// Alcove, a small single-page site.
//
// Every path serves the same page, so the site root and any deep link render the page. sendFile reads
// the file from disk per request, so an edit to public/index.html takes effect on the next request.

const express = require('express');
const path = require('path');

const app = express();
const PORT = process.env.PORT || 3000;
const INDEX = path.join(__dirname, 'public', 'index.html');

// This site is served over HTTPS, while umami is reachable only over plain HTTP, so a browser would
// block the tracker as active mixed content. These two routes re-serve umami's tracker and its
// collector on this origin, which keeps the analytics request same-origin and unblocked. Defined
// before the catch-all so they are not shadowed by it.
const UMAMI = 'http://umami-acs971378df-457131996.us-east-1.elb.amazonaws.com';

app.get('/script.js', async function (_req, res) {
  try {
    const r = await fetch(UMAMI + '/script.js');
    const body = Buffer.from(await r.arrayBuffer());
    res.status(r.status).type('application/javascript').send(body);
  } catch (e) {
    res.status(502).type('text').send('tracker unavailable');
  }
});

app.post('/api/send', express.raw({ type: '*/*', limit: '1mb' }), async function (req, res) {
  try {
    const r = await fetch(UMAMI + '/api/send', {
      method: 'POST',
      headers: {
        'content-type': req.get('content-type') || 'application/json',
        'user-agent': req.get('user-agent') || '',
        'x-forwarded-for': req.get('x-forwarded-for') || req.socket.remoteAddress || '',
      },
      body: req.body,
    });
    const body = Buffer.from(await r.arrayBuffer());
    const ct = r.headers.get('content-type');
    res.status(r.status);
    if (ct) res.type(ct);
    res.send(body);
  } catch (e) {
    res.status(502).type('text').send('collector unavailable');
  }
});

// A conventional health endpoint, defined before the catch-all so it is not shadowed by it.
app.get('/healthz', function (_req, res) {
  res.type('text').send('ok');
});

app.use(function (_req, res) {
  res.sendFile(INDEX);
});

app.listen(PORT, function () {
  console.log('alcove listening on http://localhost:' + PORT);
});
