'use strict';
const crypto = require('crypto'), fs = require('fs'), https = require('https'), os = require('os');
function creds(profile) {
  const txt = fs.readFileSync(os.homedir() + '/.aws/credentials', 'utf8');
  let cur = null; const out = {};
  for (const l of txt.split('\n')) {
    const m = l.match(/^\s*\[([^\]]+)\]\s*$/);
    if (m) { cur = m[1]; out[cur] = {}; continue; }
    const kv = l.match(/^\s*([A-Za-z_]+)\s*=\s*(.*?)\s*$/);
    if (kv && cur) out[cur][kv[1]] = kv[2];
  }
  const p = out[profile] || out['default'];
  return { ak: p.aws_access_key_id, sk: p.aws_secret_access_key, st: p.aws_session_token };
}
const [,, service, region, target, bodyFile] = process.argv;
const c = creds('acspeed-batch');
const host = service + '.' + region + '.amazonaws.com';
const body = fs.readFileSync(bodyFile);
const amzdate = new Date().toISOString().replace(/[:-]|\.\d{3}/g, '');
const datestamp = amzdate.slice(0, 8);
const h = d => crypto.createHash('sha256').update(d).digest('hex');
const hmac = (k, d) => crypto.createHmac('sha256', k).update(d).digest();
const headers = { 'content-type': 'application/x-amz-json-1.1', host, 'x-amz-date': amzdate, 'x-amz-target': target };
if (c.st) headers['x-amz-security-token'] = c.st;
const sh = Object.keys(headers).sort().join(';');
const ch = Object.keys(headers).sort().map(k => k + ':' + headers[k] + '\n').join('');
const canonReq = ['POST', '/', '', ch, sh, h(body)].join('\n');
const scope = [datestamp, region, service, 'aws4_request'].join('/');
const sts = ['AWS4-HMAC-SHA256', amzdate, scope, h(canonReq)].join('\n');
let k = hmac('AWS4' + c.sk, datestamp); k = hmac(k, region); k = hmac(k, service); k = hmac(k, 'aws4_request');
headers['authorization'] = `AWS4-HMAC-SHA256 Credential=[REDACTED:value]}/${scope}, SignedHeaders=${sh}, Signature=${crypto.createHmac('sha256', k).update(sts).digest('hex')}`;
const req = https.request({ host, path: '/', method: 'POST', headers }, res => {
  let d = ''; res.on('data', x => d += x);
  res.on('end', () => { console.log('HTTP ' + res.statusCode); console.log(d); });
});
req.on('error', e => { console.error('ERR', e.message); process.exit(1); });
req.write(body); req.end();
